target.css:
:root {
  --ink: #3d2942;
  --berry: #8d4e73;
  --cream: #fff8e9;
  --peach: #f7cda5;
}

.gelato-token {
  box-sizing: border-box;
  width: 440px;
  padding: 14px 16px;
  color: var(--ink);
  background: var(--cream);
  border: 2px solid var(--berry);
  border-radius: 16px;
}

.gelato-token header,
.gelato-token footer {
  display: flex;
  align-items: center;
}

.gelato-token header {
  gap: 9px;
}

.token-mark {
  font-size: 24px;
}

.gelato-token h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.scoop-count {
  margin-left: auto;
  padding: 4px 8px;
  color: var(--cream);
  background: var(--berry);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.gelato-token p {
  margin: 12px 0;
  font-size: 14px;
  line-height: 1.35;
}

.gelato-token footer {
  justify-content: space-between;
  padding-top: 10px;
  border-top: 1px dashed var(--peach);
  font-size: 12px;
  font-weight: 700;
}

.gelato-token button {
  padding: 7px 12px;
  color: var(--ink);
  background: var(--peach);
  border: 1px solid var(--ink);
  border-radius: 8px;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
}

